export enum PartId {
  PART_A = 'PART_A', // ภาค ก
  PART_B = 'PART_B', // ภาค ข
  PART_C = 'PART_C'  // ภาค ค
}

export interface LessonChapter {
  id: string;
  title: string;
  content: string; // Markdown content for this specific chapter
  duration?: string; // e.g., "15 min"
  isCompleted?: boolean;
  videoUrl?: string; // Google Drive Video URL
  summaryImageUrl?: string; // Google Drive Image URL
}

export interface SubTopic {
  id: string;
  title: string;
  description?: string;
  promptContext: string; // Context to send to AI
  contentPath: string; // Keep for backward compatibility or full download
  content?: string; // Legacy: Full content string
  chapters?: LessonChapter[]; // NEW: Modular content
  coverImage?: string; // URL for lesson banner image
  videoUrl?: string; // Legacy: Main topic video
}

export interface SubjectSection {
  id: string;
  title: string;
  subTopics: SubTopic[];
  isSelfStudy?: boolean; // For Part B Major
}

export interface ExamPart {
  id: PartId;
  title: string;
  subtitle: string;
  color: string;
  sections: SubjectSection[];
}

export interface Message {
  role: 'user' | 'model';
  text: string;
  id: string;
  timestamp: number;
}

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctAnswer: number; // Index 0-3
  explanation: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { BrainCircuit, CheckCircle, XCircle, RefreshCw, Trophy, Loader2, ArrowRight, Settings, BarChart, ListOrdered, ChevronLeft, ChevronRight, Clock, AlertTriangle, LogOut, BookOpen, CheckSquare } from 'lucide-react';
import { generateQuizFromContent } from '../services/geminiService';
import { QuizQuestion } from '../types';

interface QuizGeneratorProps {
  content: string;
}

const QuizGenerator: React.FC<QuizGeneratorProps> = ({ content }) => {
  const [status, setStatus] = useState<'idle' | 'setup' | 'loading' | 'taking' | 'finished'>('idle');
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [answers, setAnswers] = useState<(number | null)[]>([]); // Store all answers
  const [score, setScore] = useState(0);
  const [isChecked, setIsChecked] = useState(false); // Mode to show answers

  // Pagination State
  const ITEMS_PER_PAGE = 10;
  const [currentPage, setCurrentPage] = useState(0);

  // Setup States
  const [difficulty, setDifficulty] = useState<'easy' | 'hard'>('easy');
  const [questionCount, setQuestionCount] = useState<number>(10);
  const [subTopics, setSubTopics] = useState<string[]>([]);
  const [selectedTopic, setSelectedTopic] = useState<string>('all');
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  // Timer State
  const [startTime, setStartTime] = useState<number>(0);
  const [elapsedTime, setElapsedTime] = useState<number>(0);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  // Extract Sub-topics from Markdown content
  useEffect(() => {
    if (content) {
      // Find all headers (H1 and H2)
      const headers = content.match(/^#{1,2}\s+(.+)$/gm);
      if (headers) {
        const topics = headers
            .map(h => h.replace(/^#{1,2}\s+/, '').trim())
            .filter(topic => !topic.includes("สรุปภาพรวม") && !topic.includes("Key Takeaways"));
        setSubTopics(topics);
      }
    }
  }, [content]);

  // Timer Logic
  useEffect(() => {
    if (status === 'taking') {
      setStartTime(Date.now());
      timerRef.current = setInterval(() => {
        setElapsedTime(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [status]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const getSpeedAnalysis = () => {
    const avgTimePerQuestion = elapsedTime / questions.length;
    if (avgTimePerQuestion < 30) return { text: "เร็วมาก (Fast)", color: "text-green-600" };
    if (avgTimePerQuestion < 60) return { text: "ปานกลาง (Average)", color: "text-blue-600" };
    return { text: "ช้า (Slow)", color: "text-orange-600" };
  };

  const handleStartSetup = () => {
    setStatus('setup');
  };

  const startQuiz = async () => {
    setStatus('loading');
    const quizData = await generateQuizFromContent(content, difficulty, questionCount, selectedTopic);
    if (quizData && quizData.length > 0) {
      setQuestions(quizData);
      setAnswers(new Array(quizData.length).fill(null));
      setElapsedTime(0);
      setStatus('taking');
      setCurrentPage(0);
      setScore(0);
      setIsChecked(false);
    } else {
      alert("ไม่สามารถสร้างข้อสอบได้ในขณะนี้ อาจเกิดจากข้อจำกัดของ AI หรือเนื้อหา กรุณาลองใหม่อีกครั้ง");
      setStatus('idle');
    }
  };

  const handleAnswer = (questionIndex: number, optionIndex: number) => {
    if (isChecked) return; // Prevent changing after checking

    const newAnswers = [...answers];
    newAnswers[questionIndex] = optionIndex;
    setAnswers(newAnswers);
  };

  const calculateScore = () => {
    let newScore = 0;
    questions.forEach((q, idx) => {
        if (answers[idx] === q.correctAnswer) {
            newScore++;
        }
    });
    setScore(newScore);
    setIsChecked(true);
    setStatus('finished');
  };

  const exitQuiz = () => {
    setStatus('idle');
    setShowExitConfirm(false);
    setDifficulty('easy');
    setQuestionCount(10);
    setSelectedTopic('all');
    setIsChecked(false);
  };

  const optionPrefixes = ['ก', 'ข', 'ค', 'ง'];

  // Calculate Pagination
  const totalPages = Math.ceil(questions.length / ITEMS_PER_PAGE);
  const currentQuestions = questions.slice(currentPage * ITEMS_PER_PAGE, (currentPage + 1) * ITEMS_PER_PAGE);
  const startIndex = currentPage * ITEMS_PER_PAGE;

  const handleNextPage = () => {
      if (currentPage < totalPages - 1) {
          setCurrentPage(prev => prev + 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          // Finish
          calculateScore();
      }
  };

  const handlePrevPage = () => {
      if (currentPage > 0) {
          setCurrentPage(prev => prev - 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  // 1. Idle Screen
  if (status === 'idle') {
    return (
      <div className="bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl p-8 md:p-12 text-center text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-10">
            <BrainCircuit className="w-64 h-64" />
        </div>
        <div className="relative z-10 max-w-2xl mx-auto">
            <h2 className="text-3xl md:text-4xl font-bold mb-4">ทดสอบความเข้าใจ</h2>
            <p className="text-indigo-100 text-lg mb-8">
                สร้างข้อสอบจำลองจากเนื้อหาบทเรียนนี้ด้วย AI เพื่อวัดระดับความรู้ของคุณก่อนลงสนามจริง
            </p>
            <button
                onClick={handleStartSetup}
                className="bg-white text-indigo-700 hover:bg-indigo-50 font-bold py-4 px-10 rounded-full shadow-lg transition-all transform hover:scale-105 flex items-center gap-3 mx-auto text-lg"
            >
                <BrainCircuit className="w-6 h-6" />
                สร้างแบบทดสอบ
            </button>
        </div>
      </div>
    );
  }

  // 2. Setup Screen
  if (status === 'setup') {
    return (
      <div className="bg-white border border-indigo-100 rounded-3xl p-8 md:p-10 shadow-lg max-w-3xl mx-auto">
        <div className="text-center mb-8">
            <div className="w-16 h-16 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-4">
                <Settings className="w-8 h-8 text-indigo-600" />
            </div>
            <h2 className="text-2xl font-bold text-slate-800">ตั้งค่าแบบทดสอบ</h2>
            <p className="text-slate-500">เลือกรูปแบบข้อสอบที่คุณต้องการฝึกฝน</p>
        </div>

        <div className="grid md:grid-cols-2 gap-8 mb-10">
            <div>
                <label className="flex items-center gap-2 text-slate-700 font-semibold mb-3">
                    <BarChart className="w-5 h-5 text-indigo-500" /> ระดับความยาก
                </label>
                <div className="space-y-3">
                    <button onClick={() => setDifficulty('easy')} className={`w-full p-4 rounded-xl border-2 text-left flex justify-between items-center transition-all ${difficulty === 'easy' ? 'border-green-500 bg-green-50 text-green-800' : 'border-slate-200 hover:border-indigo-200'}`}>
                        <div><div className="font-bold">ระดับง่าย (พื้นฐาน)</div><div className="text-xs opacity-75">เน้นความจำและความเข้าใจ</div></div>
                        {difficulty === 'easy' && <CheckCircle className="w-6 h-6 text-green-600" />}
                    </button>
                    <button onClick={() => setDifficulty('hard')} className={`w-full p-4 rounded-xl border-2 text-left flex justify-between items-center transition-all ${difficulty === 'hard' ? 'border-orange-500 bg-orange-50 text-orange-800' : 'border-slate-200 hover:border-indigo-200'}`}>
                        <div><div className="font-bold">ระดับยาก (วิเคราะห์)</div><div className="text-xs opacity-75">เน้นการวิเคราะห์และประยุกต์ใช้</div></div>
                        {difficulty === 'hard' && <CheckCircle className="w-6 h-6 text-orange-600" />}
                    </button>
                </div>
            </div>

            <div className="space-y-6">
                <div>
                    <label className="flex items-center gap-2 text-slate-700 font-semibold mb-3">
                        <ListOrdered className="w-5 h-5 text-indigo-500" /> จำนวนข้อ
                    </label>
                    <div className="grid grid-cols-3 gap-3">
                        {[10, 20, 30].map((num) => (
                            <button key={num} onClick={() => setQuestionCount(num)} className={`p-4 rounded-xl border-2 text-center transition-all font-bold text-lg ${questionCount === num ? 'border-indigo-600 bg-indigo-600 text-white shadow-md' : 'border-slate-200 text-slate-600 hover:border-indigo-300'}`}>
                                {num}
                            </button>
                        ))}
                    </div>
                </div>

                {subTopics.length > 0 && (
                    <div>
                        <label className="flex items-center gap-2 text-slate-700 font-semibold mb-3">
                            <BookOpen className="w-5 h-5 text-indigo-500" /> เลือกหัวข้อเฉพาะ
                        </label>
                        <select value={selectedTopic} onChange={(e) => setSelectedTopic(e.target.value)} className="w-full p-3 rounded-xl border-2 border-slate-200 bg-white text-slate-700 focus:outline-none focus:border-indigo-500 transition-colors">
                            <option value="all">ครอบคลุมทุกเนื้อหา (แนะนำ)</option>
                            {subTopics.map((topic, idx) => (
                                <option key={idx} value={topic}>{topic}</option>
                            ))}
                        </select>
                    </div>
                )}
            </div>
        </div>

        <div className="flex justify-center gap-4">
            <button onClick={() => setStatus('idle')} className="px-6 py-3 rounded-full text-slate-500 hover:bg-slate-100 font-medium transition-colors">ยกเลิก</button>
            <button onClick={startQuiz} className="bg-indigo-600 text-white hover:bg-indigo-700 font-bold py-3 px-10 rounded-full shadow-lg transition-all transform hover:scale-105 flex items-center gap-2">เริ่มทำข้อสอบ <ArrowRight className="w-5 h-5" /></button>
        </div>
      </div>
    );
  }

  // 3. Loading Screen
  if (status === 'loading') {
    return (
      <div className="bg-white border border-indigo-100 rounded-3xl p-12 text-center shadow-lg animate-pulse">
        <Loader2 className="w-16 h-16 text-indigo-600 animate-spin mx-auto mb-6" />
        <h3 className="text-2xl font-bold text-slate-800 mb-2">กำลังออกข้อสอบ...</h3>
        <p className="text-slate-500 mb-2">AI กำลังวิเคราะห์เนื้อหาบทเรียนและสร้างโจทย์</p>
        <p className="text-slate-400 text-sm mb-4">กรุณารอสักครู่ ใช้เวลาประมาณ 30 - 60 วินาที</p>
      </div>
    );
  }

  // 4. Finished Screen (Score)
  if (status === 'finished') {
    return (
      <div className="bg-white border border-slate-200 rounded-3xl p-8 md:p-12 text-center shadow-xl">
        <div className="w-24 h-24 bg-yellow-100 rounded-full flex items-center justify-center mx-auto mb-6">
            <Trophy className="w-12 h-12 text-yellow-600" />
        </div>
        <h2 className="text-3xl font-bold text-slate-800 mb-2">สรุปผลคะแนน</h2>
        <div className="text-5xl font-extrabold text-indigo-600 mb-6">
            {score} / {questions.length}
        </div>

        <div className="flex justify-center items-center gap-6 mb-8 text-sm md:text-base bg-slate-50 p-4 rounded-xl inline-flex mx-auto">
            <div className="flex items-center gap-2">
                <Clock className="w-5 h-5 text-slate-500" />
                <span className="font-semibold text-slate-700">เวลาที่ใช้: {formatTime(elapsedTime)}</span>
            </div>
            <div className="w-px h-6 bg-slate-300"></div>
            <div className="flex items-center gap-2">
                <BarChart className="w-5 h-5 text-slate-500" />
                <span className={`font-bold ${getSpeedAnalysis().color}`}>
                    ความเร็ว: {getSpeedAnalysis().text}
                </span>
            </div>
        </div>

        {/* Answer Key Review Section */}
        <div className="mt-8 mb-8 text-left max-w-3xl mx-auto">
             <h3 className="text-xl font-bold text-slate-800 mb-4 border-b pb-2">เฉลยคำตอบ</h3>
             <div className="space-y-4 max-h-[400px] overflow-y-auto custom-scrollbar pr-2">
                 {questions.map((q, idx) => (
                     <div key={idx} className={`p-4 rounded-lg border ${answers[idx] === q.correctAnswer ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'}`}>
                         <div className="flex gap-2 mb-2">
                             <span className="font-bold text-slate-700">{idx + 1}.</span>
                             <span className="font-medium text-slate-900">{q.question}</span>
                         </div>
                         <div className="text-sm ml-6 space-y-1">
                             <p className={answers[idx] === q.correctAnswer ? 'text-green-700' : 'text-red-600'}>
                                 คำตอบของคุณ: {answers[idx] !== null ? q.options[answers[idx]!] : 'ไม่ได้ตอบ'}
                             </p>
                             {answers[idx] !== q.correctAnswer && (
                                 <p className="text-green-700 font-semibold">
                                     คำตอบที่ถูก: {q.options[q.correctAnswer]}
                                 </p>
                             )}
                             <div className="mt-2 text-slate-600 text-xs bg-white/50 p-2 rounded">
                                 <span className="font-bold">อธิบาย:</span> {q.explanation}
                             </div>
                         </div>
                     </div>
                 ))}
             </div>
        </div>

        <div className="flex justify-center gap-4">
            <button onClick={exitQuiz} className="text-slate-500 hover:text-slate-800 font-medium px-6 py-3 transition-colors">กลับหน้าหลัก</button>
            <button onClick={startQuiz} className="bg-indigo-600 text-white hover:bg-indigo-700 font-bold py-3 px-8 rounded-full transition-colors inline-flex items-center gap-2"><RefreshCw className="w-5 h-5" /> สอบใหม่อีกครั้ง</button>
        </div>
      </div>
    );
  }

  // 5. Taking Quiz Screen (List View)
  return (
    <div className="bg-white border border-slate-200 rounded-3xl overflow-hidden shadow-xl relative min-h-[600px] flex flex-col">
      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white rounded-2xl p-6 md:p-8 max-w-md w-full shadow-2xl text-center">
                <AlertTriangle className="w-12 h-12 text-red-600 mx-auto mb-4" />
                <h3 className="text-xl font-bold text-slate-800 mb-2">ยืนยันการออก</h3>
                <p className="text-slate-600 mb-6">คุณต้องการออกจากแบบทดสอบใช่หรือไม่? คะแนนจะไม่ถูกบันทึก</p>
                <div className="flex gap-3">
                    <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-2 rounded-lg border border-slate-300">ยกเลิก</button>
                    <button onClick={exitQuiz} className="flex-1 py-2 rounded-lg bg-red-600 text-white">ออกทันที</button>
                </div>
            </div>
        </div>
      )}

      {/* Header */}
      <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center sticky top-0 z-20 shadow-sm">
        <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 text-indigo-600 font-bold bg-white px-3 py-1 rounded-full shadow-sm border border-slate-200">
                <Clock className="w-4 h-4" />
                <span className="font-mono">{formatTime(elapsedTime)}</span>
            </div>
            <div className="text-sm text-slate-600 font-medium">
                หน้า {currentPage + 1} / {totalPages} (ข้อที่ {startIndex + 1}-{Math.min(startIndex + ITEMS_PER_PAGE, questions.length)})
            </div>
        </div>
        <button onClick={() => setShowExitConfirm(true)} className="text-slate-400 hover:text-red-500 p-2"><LogOut className="w-5 h-5" /></button>
      </div>

      {/* Question List */}
      <div className="p-6 md:p-10 space-y-8 flex-1 overflow-y-auto">
        {currentQuestions.map((q, localIdx) => {
            const globalIdx = startIndex + localIdx;
            return (
                <div key={q.id} className="pb-8 border-b border-slate-100 last:border-0">
                    <h3 className="text-lg font-bold text-slate-800 mb-4 flex gap-3">
                        <span className="bg-indigo-100 text-indigo-700 w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 text-sm">
                            {globalIdx + 1}
                        </span>
                        {q.question}
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 ml-11">
                        {q.options.map((option, optIdx) => (
                            <button
                                key={optIdx}
                                onClick={() => handleAnswer(globalIdx, optIdx)}
                                className={`p-3 rounded-lg border text-left text-base transition-all flex items-center gap-3
                                    ${answers[globalIdx] === optIdx 
                                        ? 'border-indigo-600 bg-indigo-50 text-indigo-900 ring-1 ring-indigo-600' 
                                        : 'border-slate-200 hover:border-indigo-300 hover:bg-slate-50 text-slate-700'
                                    }`}
                            >
                                <div className={`w-6 h-6 rounded-full border flex items-center justify-center flex-shrink-0
                                    ${answers[globalIdx] === optIdx ? 'bg-indigo-600 border-indigo-600 text-white' : 'border-slate-300 text-slate-400'}
                                `}>
                                    {answers[globalIdx] === optIdx ? <CheckCircle className="w-4 h-4" /> : <span className="text-xs">{optionPrefixes[optIdx]}</span>}
                                </div>
                                {option}
                            </button>
                        ))}
                    </div>
                </div>
            );
        })}
      </div>

      {/* Footer Navigation */}
      <div className="p-6 border-t border-slate-200 bg-slate-50 flex justify-between items-center sticky bottom-0 z-20">
          <button
            onClick={handlePrevPage}
            disabled={currentPage === 0}
            className={`flex items-center gap-2 px-5 py-2.5 rounded-full font-medium transition-colors ${currentPage === 0 ? 'text-slate-300 cursor-not-allowed' : 'text-slate-600 hover:bg-white hover:shadow-sm'}`}
          >
              <ChevronLeft className="w-5 h-5" /> ย้อนกลับ
          </button>

          {currentPage < totalPages - 1 ? (
              <button
                onClick={handleNextPage}
                className="bg-indigo-600 text-white hover:bg-indigo-700 font-bold py-3 px-8 rounded-full shadow-md hover:shadow-lg transition-all flex items-center gap-2"
              >
                  หน้าถัดไป <ChevronRight className="w-5 h-5" />
              </button>
          ) : (
              <button
                onClick={calculateScore}
                className="bg-green-600 text-white hover:bg-green-700 font-bold py-3 px-8 rounded-full shadow-md hover:shadow-lg transition-all flex items-center gap-2"
              >
                  <CheckSquare className="w-5 h-5" /> ส่งคำตอบ (ตรวจคะแนน)
              </button>
          )}
      </div>
    </div>
  );
};

export default QuizGenerator;

import React, { useRef, useEffect, useState } from 'react';
import { ChevronLeft, Loader2, AlertCircle, BookOpen, Lightbulb, Star, CheckCircle, PlayCircle, Menu, ArrowRight, Video, Image as ImageIcon } from 'lucide-react';
import { SubTopic } from '../types';
import ReactMarkdown, { Components } from 'react-markdown';
import ChatBot from './ChatBot';
import remarkGfm from 'remark-gfm';
import QuizGenerator from './QuizGenerator';

interface LessonViewProps {
  topic: SubTopic;
  onBack: () => void;
}

const LessonView: React.FC<LessonViewProps> = ({ topic, onBack }) => {
  const contentRef = useRef<HTMLDivElement>(null);
  const [content, setContent] = useState<string>('');
  const [fullLessonContent, setFullLessonContent] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  // Chapter State
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [completedChapters, setCompletedChapters] = useState<Set<number>>(new Set());
  const [isSidebarOpen, setIsSidebarOpen] = useState(false); // Mobile sidebar toggle

  // Check if this topic has modular chapters
  const hasChapters = topic.chapters && topic.chapters.length > 0;
  const currentChapter = hasChapters ? topic.chapters![currentChapterIndex] : null;

  // Load content based on whether it's modular or legacy
  useEffect(() => {
    const loadContent = async () => {
      setIsLoading(true);
      setError(null);
      setContent('');

      if (hasChapters) {
        // Modular mode: Content comes from current chapter
        setContent(currentChapter!.content);

        // Prepare full content for QuizGenerator (combine all chapters)
        const combined = topic.chapters!.map(c => c.content).join('\n\n');
        setFullLessonContent(combined);

        setIsLoading(false);
      } else {
        // Legacy mode: Load full content string or fetch from path
        if (topic.content) {
          setContent(topic.content);
          setFullLessonContent(topic.content);
          setIsLoading(false);
        } else {
          try {
            const response = await fetch(topic.contentPath);
            if (!response.ok) throw new Error("Failed to load content");
            const text = await response.text();
            if (text.trim().startsWith('<!DOCTYPE html>')) throw new Error("Content 404");
            setContent(text);
            setFullLessonContent(text);
          } catch (err) {
            console.error(err);
            setError("ไม่พบไฟล์เนื้อหาบทเรียนนี้");
          } finally {
            setIsLoading(false);
          }
        }
      }
    };

    loadContent();
    // Reset scroll on chapter change
    if (contentRef.current) {
        contentRef.current.scrollTop = 0;
    }
  }, [topic, currentChapterIndex, hasChapters, currentChapter]);

  const handleNextStep = () => {
    // Mark current as complete
    const newCompleted = new Set(completedChapters);
    newCompleted.add(currentChapterIndex);
    setCompletedChapters(newCompleted);

    if (hasChapters) {
        if (currentChapterIndex < topic.chapters!.length - 1) {
