                            {hasChapters && currentChapterIndex === topic.chapters!.length - 1 ? (
                                <div>
                                    <ReactMarkdown components={markdownComponents} remarkPlugins={[remarkGfm]}>
                                        {content}
                                    </ReactMarkdown>
                                    <div className="mt-12 pt-8 border-t border-slate-100">
                                        <QuizGenerator content={fullLessonContent} />
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <ReactMarkdown components={markdownComponents} remarkPlugins={[remarkGfm]}>
                                        {content}
                                    </ReactMarkdown>

                                    {/* Summary Image Section (Bottom of Page) */}
                                    {currentSummaryImg && (
                                        <div className="mt-12 mb-8">
                                            <div className="flex items-center gap-3 mb-4">
                                                <div className="p-2 bg-pink-100 rounded-lg text-pink-600">
                                                    <ImageIcon className="w-6 h-6" />
                                                </div>
                                                <h3 className="text-xl font-bold text-slate-800">สรุปภาพรวมบทเรียน (Infographic)</h3>
                                            </div>
                                            <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                                                <img 
                                                    src={getGoogleDriveImageUrl(currentSummaryImg) || ''} 
                                                    alt="Lesson Summary Infographic" 
                                                    className="w-full h-auto"
                                                    loading="lazy"
                                                />
                                            </div>
                                        </div>
                                    )}
                                </>
                            )}
                        </div>
                    )}

                    {/* Footer Navigation Button */}
                    <div className="mt-12 pt-12 border-t border-slate-100 flex justify-center pb-8">
                        <button
                            onClick={handleNextStep}
                            className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 px-12 rounded-full shadow-lg hover:shadow-xl transition-all flex items-center gap-3 transform hover:scale-105 text-lg"
                        >
                            <span>
                                {hasChapters && currentChapterIndex === topic.chapters!.length - 1 
                                    ? "ฉันเข้าใจบทเรียนนี้แล้ว (กลับสู่เมนูหลัก)" 
                                    : "บทเรียนถัดไป"
                                }
                            </span>
                            <ArrowRight className="w-6 h-6" />
                        </button>
                    </div>
                </div>
            </div>
        </div>

        {/* ChatBot */}
        {!isLoading && !error && (
            <ChatBot context={content} topicTitle={hasChapters ? currentChapter!.title : topic.title} />
        )}
      </main>
    </div>
  );
};

