import React, { useState, useEffect, useRef } from 'react';
import { BrainCircuit, CheckCircle, XCircle, RefreshCw, Trophy, Loader2, ArrowRight, Settings, BarChart, ListOrdered, ChevronLeft, ChevronRight, Clock, AlertTriangle, LogOut, BookOpen, CheckSquare } from 'lucide-react';
import { generateQuizFromContent } from '../services/geminiService';
import { QuizQuestion } from '../types';

interface QuizGeneratorProps {
  content: string;
}

const QuizGenerator: React.FC<QuizGeneratorProps> = ({ content }) => {
  const [status, setStatus] = useState<'idle' | 'setup' | 'loading' | 'taking' | 'finished'>('idle');
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [answers, setAnswers] = useState<(number | null)[]>([]); // Store all answers
  const [score, setScore] = useState(0);
  const [isChecked, setIsChecked] = useState(false); // Mode to show answers

  // Pagination State
  const ITEMS_PER_PAGE = 10;
  const [currentPage, setCurrentPage] = useState(0);

  // Setup States
  const [difficulty, setDifficulty] = useState<'easy' | 'hard'>('easy');
  const [questionCount, setQuestionCount] = useState<number>(10);
  const [subTopics, setSubTopics] = useState<string[]>([]);
  const [selectedTopic, setSelectedTopic] = useState<string>('all');
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  // Timer State
  const [startTime, setStartTime] = useState<number>(0);
  const [elapsedTime, setElapsedTime] = useState<number>(0);
  const timerRef = useRef<number | null>(null);

  // Extract Sub-topics from Markdown content
  useEffect(() => {
    if (content) {
      // Find all headers (H1 and H2)
      const headers = content.match(/^#{1,2}\s+(.+)$/gm);
      if (headers) {
        const topics = headers
            .map(h => h.replace(/^#{1,2}\s+/, '').trim())
            .filter(topic => !topic.includes("สรุปภาพรวม") && !topic.includes("Key Takeaways"));
        setSubTopics(topics);
      }
    }
  }, [content]);

  // Timer Logic
  useEffect(() => {
    if (status === 'taking') {
      setStartTime(Date.now());
      timerRef.current = window.setInterval(() => {
        setElapsedTime(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [status]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  const getSpeedAnalysis = () => {
    const avgTimePerQuestion = elapsedTime / questions.length;
    if (avgTimePerQuestion < 30) return { text: "เร็วมาก (Fast)", color: "text-green-600" };
    if (avgTimePerQuestion < 60) return { text: "ปานกลาง (Average)", color: "text-blue-600" };
    return { text: "ช้า (Slow)", color: "text-orange-600" };
  };

  const handleStartSetup = () => {
    setStatus('setup');
  };

  const startQuiz = async () => {
    setStatus('loading');
    const quizData = await generateQuizFromContent(content, difficulty, questionCount, selectedTopic);
    if (quizData && quizData.length > 0) {
      setQuestions(quizData);
      setAnswers(new Array(quizData.length).fill(null));
      setElapsedTime(0);
      setStatus('taking');
      setCurrentPage(0);
      setScore(0);
      setIsChecked(false);
    } else {
      alert("ไม่สามารถสร้างข้อสอบได้ในขณะนี้ อาจเกิดจากข้อจำกัดของ AI หรือเนื้อหา กรุณาลองใหม่อีกครั้ง");
      setStatus('idle');
    }
  };

  const handleAnswer = (questionIndex: number, optionIndex: number) => {
    if (isChecked) return; // Prevent changing after checking

    const newAnswers = [...answers];
    newAnswers[questionIndex] = optionIndex;
    setAnswers(newAnswers);
  };

  const calculateScore = () => {
    let newScore = 0;
    questions.forEach((q, idx) => {
        if (answers[idx] === q.correctAnswer) {
            newScore++;
        }
    });
    setScore(newScore);
    setIsChecked(true);
    setStatus('finished');
  };

  const exitQuiz = () => {
    setStatus('idle');
    setShowExitConfirm(false);
    setDifficulty('easy');
    setQuestionCount(10);
    setSelectedTopic('all');
    setIsChecked(false);
  };

  const optionPrefixes = ['ก', 'ข', 'ค', 'ง'];

  // Calculate Pagination
  const totalPages = Math.ceil(questions.length / ITEMS_PER_PAGE);
  const currentQuestions = questions.slice(currentPage * ITEMS_PER_PAGE, (currentPage + 1) * ITEMS_PER_PAGE);
  const startIndex = currentPage * ITEMS_PER_PAGE;

  const handleNextPage = () => {
      if (currentPage < totalPages - 1) {
          setCurrentPage(prev => prev + 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      } else {
          // Finish
          calculateScore();
      }
  };

  const handlePrevPage = () => {
      if (currentPage > 0) {
          setCurrentPage(prev => prev - 1);
          window.scrollTo({ top: 0, behavior: 'smooth' });
      }
  };

  // 1. Idle Screen
  if (status === 'idle') {
    return (
      <div className="bg-gradient-to-br from-indigo-600 to-violet-700 rounded-3xl p-8 md:p-12 text-center text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-10">
            <BrainCircuit className="w-64 h-64" />
        </div>
        <div className="relative z-10 max-w-2xl mx-auto">
            <h2 className="text-3xl md:text-4xl font-bold mb-4">ทดสอบความเข้าใจ</h2>
            <p className="text-indigo-100 text-lg mb-8">
                สร้างข้อสอบจำลองจากเนื้อหาบทเรียนนี้ด้วย AI เพื่อวัดระดับความรู้ของคุณก่อนลงสนามจริง
            </p>
            <button
                onClick={handleStartSetup}
                className="bg-white text-indigo-700 hover:bg-indigo-50 font-bold py-4 px-10 rounded-full shadow-lg transition-all transform hover:scale-105 flex items-center gap-3 mx-auto text-lg"
            >
                <BrainCircuit className="w-6 h-6" />
                สร้างแบบทดสอบ
            </button>
        </div>
      </div>
    );
